-- Club challenges: mode/server catalog, audience, prize scope, progress, leave season.

CREATE OR REPLACE FUNCTION public.club_leave_cooldown_interval(p_leave_count integer)
RETURNS interval LANGUAGE sql IMMUTABLE AS $$
  SELECT CASE
    WHEN COALESCE(p_leave_count, 0) <= 1 THEN interval '1 hour'
    WHEN p_leave_count = 2 THEN interval '1 day'
    WHEN p_leave_count = 3 THEN interval '7 days'
    ELSE interval '30 days'
  END;
$$;

CREATE OR REPLACE FUNCTION public.club_leave_next_count(p_steam bigint)
RETURNS integer LANGUAGE plpgsql STABLE AS $$
DECLARE
  rec record;
BEGIN
  SELECT leave_count, last_left_at
    INTO rec
    FROM public.club_leave_cooldowns
   WHERE steam_id = p_steam;
  IF NOT FOUND THEN
    RETURN 1;
  END IF;
  IF rec.last_left_at IS NULL OR rec.last_left_at <= now() - interval '30 days' THEN
    RETURN 1;
  END IF;
  RETURN LEAST(GREATEST(COALESCE(rec.leave_count, 0), 0) + 1, 4);
END;
$$;

ALTER TABLE public.club_members
  ADD COLUMN IF NOT EXISTS is_vip boolean NOT NULL DEFAULT false;

ALTER TABLE public.club_challenge_catalog
  ADD COLUMN IF NOT EXISTS server_mode text NOT NULL DEFAULT 'dm',
  ADD COLUMN IF NOT EXISTS weapon text NOT NULL DEFAULT '',
  ADD COLUMN IF NOT EXISTS metric text NOT NULL DEFAULT 'kills',
  ADD COLUMN IF NOT EXISTS target integer NOT NULL DEFAULT 10;

ALTER TABLE public.club_challenges
  ADD COLUMN IF NOT EXISTS prize_scope text NOT NULL DEFAULT 'club',
  ADD COLUMN IF NOT EXISTS audience text NOT NULL DEFAULT 'club';

ALTER TABLE public.club_challenges
  DROP CONSTRAINT IF EXISTS club_challenges_prize_scope_chk;
ALTER TABLE public.club_challenges
  ADD CONSTRAINT club_challenges_prize_scope_chk
  CHECK (prize_scope IN ('club', 'site'));
ALTER TABLE public.club_challenges
  DROP CONSTRAINT IF EXISTS club_challenges_audience_chk;
ALTER TABLE public.club_challenges
  ADD CONSTRAINT club_challenges_audience_chk
  CHECK (audience IN ('site', 'club', 'club_vip', 'players'));

CREATE TABLE IF NOT EXISTS public.club_challenge_targets (
  challenge_id uuid NOT NULL REFERENCES public.club_challenges(id) ON UPDATE CASCADE ON DELETE CASCADE,
  steam_id bigint NOT NULL REFERENCES public.players(steam_id) ON UPDATE CASCADE ON DELETE CASCADE,
  PRIMARY KEY (challenge_id, steam_id)
);

CREATE TABLE IF NOT EXISTS public.club_challenge_progress (
  challenge_id uuid NOT NULL REFERENCES public.club_challenges(id) ON UPDATE CASCADE ON DELETE CASCADE,
  steam_id bigint NOT NULL REFERENCES public.players(steam_id) ON UPDATE CASCADE ON DELETE CASCADE,
  progress integer NOT NULL DEFAULT 0 CHECK (progress >= 0),
  completed_at timestamptz,
  updated_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (challenge_id, steam_id)
);
CREATE INDEX IF NOT EXISTS club_challenge_progress_steam_idx
  ON public.club_challenge_progress (steam_id, updated_at DESC);

CREATE OR REPLACE FUNCTION public.club_challenge_is_visible(
  challenge_row public.club_challenges,
  hasura_session json
)
RETURNS boolean LANGUAGE plpgsql STABLE AS $$
DECLARE
  uid bigint;
BEGIN
  BEGIN
    uid := nullif(hasura_session ->> 'x-hasura-user-id', '')::bigint;
  EXCEPTION WHEN others THEN
    uid := NULL;
  END;
  IF NOT challenge_row.active OR challenge_row.ends_at <= now() THEN
    IF uid IS NOT NULL AND EXISTS (
      SELECT 1 FROM public.clubs c
       WHERE c.id = challenge_row.club_id AND c.owner_steam_id = uid
    ) THEN
      RETURN true;
    END IF;
    RETURN false;
  END IF;
  IF challenge_row.audience = 'site' THEN
    RETURN true;
  END IF;
  IF uid IS NULL THEN
    RETURN false;
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.clubs c
     WHERE c.id = challenge_row.club_id AND c.owner_steam_id = uid
  ) THEN
    RETURN true;
  END IF;
  IF challenge_row.audience = 'club' THEN
    RETURN EXISTS (
      SELECT 1 FROM public.club_members m
       WHERE m.club_id = challenge_row.club_id AND m.steam_id = uid
    );
  END IF;
  IF challenge_row.audience = 'club_vip' THEN
    RETURN EXISTS (
      SELECT 1 FROM public.club_members m
       WHERE m.club_id = challenge_row.club_id AND m.steam_id = uid AND m.is_vip
    );
  END IF;
  IF challenge_row.audience = 'players' THEN
    RETURN EXISTS (
      SELECT 1 FROM public.club_challenge_targets t
       WHERE t.challenge_id = challenge_row.id AND t.steam_id = uid
    );
  END IF;
  RETURN false;
END;
$$;

DELETE FROM public.club_challenge_progress;
DELETE FROM public.club_challenge_targets;
DELETE FROM public.club_challenges;
DELETE FROM public.club_challenge_catalog;

